  const pattern = /^## Step\s+(\d+)\s*$/gm;
  let match;
  while ((match = pattern.exec(agentsText)) !== null) {
    const step = Number(match[1]);
    if (!seen.has(step)) {
      seen.add(step);
      found.push(step);
    }
  }
  if (found.length === 0) {
    throw new Error("Agents.md contains no procedure steps matching '## Step N'.");
  }
  return found.sort((a, b) => a - b);
}

